def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                v, wt = cache[key]
                if t - wt >= ttl:
                    del cache[key]
            if key in cache:
                # update existing, not expired
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                # need to check capacity before inserting new key
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t - wt >= ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(v)
            else:
                results.append(-1)
    return results

